<?php require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_admin();$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['_csrf']??''))$error='Invalid request.';else{try{$pdo->beginTransaction();$status=in_array($_POST['account_status']??'', ['active','inactive','locked'])?$_POST['account_status']:'active';$pdo->prepare("UPDATE users SET mobile=?,email=?,account_status=? WHERE id=?")->execute([trim($_POST['mobile']),trim($_POST['email']),$status,$id]);$pdo->prepare("UPDATE user_profiles SET first_name=?,last_name=?,father_name=?,mother_name=?,date_of_birth=?,gender=?,category=?,domicile_state=? WHERE user_id=?")->execute([trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['father_name']),trim($_POST['mother_name']),$_POST['date_of_birth']?:null,$_POST['gender'],$_POST['category'],trim($_POST['domicile_state']),$id]);$pdo->prepare("INSERT INTO audit_logs(admin_id,action,module,record_id,created_at) VALUES(?,?,?,?,NOW())")->execute([$_SESSION['admin_id'],'UPDATE','users',$id]);$pdo->commit();flash('success','User updated.');redirect('user-view.php?id='.$id);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not update user.';}}}
$st=$pdo->prepare("SELECT u.*,p.* FROM users u LEFT JOIN user_profiles p ON p.user_id=u.id WHERE u.id=?");$st->execute([$id]);$u=$st->fetch();if(!$u)redirect('users.php');$page_title='User Details';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?><div class="page-head"><div><h1>User Details</h1><p class="muted"><?=e($u['user_uid'])?></p></div><a class="btn btn-light" href="users.php">← Users</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form class="card form-grid" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($id)?>"><label>First Name<input name="first_name" value="<?=e($u['first_name'])?>"></label><label>Last Name<input name="last_name" value="<?=e($u['last_name'])?>"></label><label>Mobile<input name="mobile" value="<?=e($u['mobile'])?>"></label><label>Email<input name="email" value="<?=e($u['email'])?>"></label><label>Father Name<input name="father_name" value="<?=e($u['father_name'])?>"></label><label>Mother Name<input name="mother_name" value="<?=e($u['mother_name'])?>"></label><label>DOB<input type="date" name="date_of_birth" value="<?=e($u['date_of_birth'])?>"></label><label>Gender<input name="gender" value="<?=e($u['gender'])?>"></label><label>Category<input name="category" value="<?=e($u['category'])?>"></label><label>Domicile State<input name="domicile_state" value="<?=e($u['domicile_state'])?>"></label><label>Status<select name="account_status"><?php foreach(['active','inactive','locked'] as $s):?><option <?=($u['account_status']===$s?'selected':'')?>><?=$s?></option><?php endforeach;?></select></label><div class="form-actions"><button class="btn btn-primary">Save Changes</button><a class="btn btn-light" href="reset-user-password.php?id=<?=e($id)?>">Reset Password</a></div></form><?php require '../includes/footer.php';?>